/* Nauren RPG — Compêndios oficiais (auto-semeadura, Torre, Bestiário, mascotes). Separado do nauren.mjs na 0.94.22. */
import { NAUREN_CAPACIDADE_POR_NOME, NAUREN_CORES_PINTURA, NAUREN_EQUIPAMENTO_CLASSE_LIVRO, NaurenActorSheet, NaurenAlvoHelper, NaurenCondicaoData, NaurenHabilidadeData, NaurenMagiaData, campoAcao, campoModificador, naurenAtorTemRecurso, naurenClamparRecursosAoMaximo, naurenEhCondicaoModelo, naurenEquipRecomendadoPreenchido, naurenFixarTipoAlcanceSemeado, naurenInterpretarModificador, naurenMontarDescricao, naurenNomeDoRecurso, naurenPostarCard, naurenPreencherRecursosNoMaximo, naurenProcessarGatilhos, naurenRecursoEstaTravado, naurenResetarCompendios, naurenUuidPorSeed } from "../nauren.mjs";
/* =======================================
 * 7. COMPÊNDIOS OFICIAIS DO SISTEMA (auto-semeadura)
 * =======================================
 * Compêndios "de mundo": este ambiente de desenvolvimento não tem acesso
 * a rede pra compilar um pacote binário (LevelDB) de verdade via a
 * ferramenta oficial do Foundry, então em vez disso o PRÓPRIO SISTEMA
 * cria e povoa os compêndios automaticamente na primeira vez que o mundo
 * carrega, usando a API real do Foundry (CompendiumCollection.
 * createCompendium) - o resultado final pro usuário é idêntico a abrir
 * um mundo com compêndios já prontos. Cada fase futura (novas classes,
 * itens, etc.) só adiciona o que ainda não existe (checado por uma flag
 * "flags.nauren.seedId" única por item), nunca duplica nem sobrescreve o
 * que já foi criado - uma vez que um item nasce no compêndio, ele é
 * considerado "propriedade do usuário" e pode ser editado livremente sem
 * risco de ser resetado numa atualização futura do sistema.
 */

// Seed IDs do "Equipamento Inicial" (Cap. II do manual, "itens de categoria
// simples/leves" conforme o Destino) - usados pelo Criador de Personagem
// (que resolve estes UUIDs em tempo de execução, na etapa "4. Equipamento"
// da criação). As Classes NÃO duplicam mais esta escolha no próprio nível
// 1 (bug real corrigido: cada Classe tinha seu próprio "escolhaItens" com
// o mesmo pool, então quem criava a ficha pelo Criador de Personagem via
// a mesma pergunta duas vezes - uma no Criador, outra ao a Classe ser
// concedida). Isto aqui é a única fonte de verdade agora.
/** Padrão do Criador: todas as armas e só as armaduras simples (o Mestre muda item a item na aba Geral). */
const NAUREN_SEED_IDS_INICIAIS_PADRAO = new Set([
  "arma-leve", "arma-media", "arma-alcance", "arma-pesada", "arma-distancia-arco", "arma-distancia-besta", "arma-distancia-arma-de-fogo", "arma-catalisador-gariart",
  "armadura-robe-simples", "armadura-couro-simples", "armadura-cota-simples", "armadura-capa-simples", "armadura-botas-simples", "escudo-simples"
]);
/** O item aparece na escolha de equipamento do Criador? (respeita a escolha do Mestre no item). */
function naurenDisponivelNoInicio(entrada) {
  const escolha = entrada?.system?.disponivelNoInicio ?? "";
  if (escolha === "sim") return true;
  if (escolha === "nao") return false;
  if (game.settings.get("nauren", "criadorTodoEquipamento")) return NAUREN_SEED_IDS_EQUIPAMENTO_INICIAL.armas.includes(entrada?.flags?.nauren?.seedId) || NAUREN_SEED_IDS_EQUIPAMENTO_INICIAL.armaduras.includes(entrada?.flags?.nauren?.seedId);
  return NAUREN_SEED_IDS_INICIAIS_PADRAO.has(entrada?.flags?.nauren?.seedId);
}

const NAUREN_SEED_IDS_EQUIPAMENTO_INICIAL = {
  armas: [
    "arma-leve", "arma-media", "arma-alcance", "arma-pesada",
    "arma-distancia-arco", "arma-distancia-besta", "arma-distancia-arma-de-fogo", "arma-catalisador-gariart"
  ],
  armaduras: [
    "armadura-robe-simples", "armadura-manto-cerimonial", "armadura-couro-simples", "armadura-couro-reforcado",
    "armadura-cota-simples", "armadura-cota-reforcada", "armadura-placa-simples", "armadura-placa-reforcada",
    "armadura-capa-simples", "armadura-capa-reforcada", "armadura-botas-simples", "armadura-grevas-reforcadas",
    "escudo-simples", "escudo-medio", "escudo-grande"
  ]
};

const NAUREN_PACKS_DEFINICAO = {
  armas: { label: "Nauren - Armas", type: "Item" },
  armaduras: { label: "Nauren - Armaduras", type: "Item" },
  condicoes: { label: "Nauren - Condições e Venenos", type: "Item" },
  efeitos: { label: "Nauren - Efeitos", type: "Item" },
  pigmentos: { label: "Nauren - Pigmentos", type: "Item" },
  magias: { label: "Nauren - Magias", type: "Item" },
  habilidades: { label: "Nauren - Habilidades de Classe", type: "Item" },
  classes: { label: "Nauren - Classes", type: "Item" },
  subclasses: { label: "Nauren - Subclasses", type: "Item" },
  peculiaridades: { label: "Nauren - Peculiaridades (Benefícios e Fardos)", type: "Item" },
  mascotes: { label: "Nauren - Mascotes", type: "Actor" },
  regras: { label: "Nauren - Regras", type: "JournalEntry" },
  torre: { label: "Itens da Torre Infinita", type: "Item" },
  // "apenasMestre": conteúdo que só faz sentido o Mestre folhear (fichas
  // de monstro prontas pra arrastar pro mundo) - jogadores não precisam
  // navegar isso diretamente. Ver naurenObterOuCriarPacks/
  // naurenGarantirOwnershipApenasMestre pra como isso é aplicado.
  monstros: { label: "Nauren - Bestiário (Codex Bestiariun)", type: "Actor", apenasMestre: true },
  // Habilidades prontas para montar monstros e NPCs (Criador de Monstros): só o Mestre vê.
  habMonstros: { label: "Nauren - Habilidades de Monstros", type: "Item", apenasMestre: true },
};

// Ownership que deixa um compêndio visível SÓ pro Mestre (e Assistente) -
// PLAYER e TRUSTED ficam sem nenhum acesso, nem "ver que existe" na
// barra lateral.
const NAUREN_OWNERSHIP_APENAS_MESTRE = { PLAYER: "NONE", TRUSTED: "NONE", ASSISTANT: "OWNER", GAMEMASTER: "OWNER" };

/**
 * Acha (ou cria, se ainda não existir) cada compêndio de mundo do
 * sistema, devolvendo um mapa {chave: CompendiumCollection}. Pacotes
 * marcados com "apenasMestre" (ver NAUREN_PACKS_DEFINICAO) recebem
 * ownership restrito a Mestre/Assistente - tanto na CRIAÇÃO quanto,
 * pra pacotes que JÁ EXISTEM no mundo (o caso mais comum, já que isso
 * só roda 1x por instalação), tentando reconfigurar via
 * "pack.configure({ownership})" no carregamento.
 *
 * ⚠️ Existe um bug conhecido e ainda aberto no Foundry V13 Stable
 * (build 347+, issue #13283 do repositório oficial): chamadas a
 * "CompendiumCollection#configure({ownership: ...})" podem ser
 * silenciosamente descartadas (o dado nunca persiste no setting do
 * mundo). Por isso este código LOGA um aviso pro Mestre confirmar
 * visualmente se funcionou, em vez de assumir que funcionou. Se não
 * funcionar sozinho, o caminho garantido (sempre funciona, é nativo do
 * Foundry) é manual: clique-direito no compêndio na barra lateral →
 * "Toggle Visibility".
 */
async function naurenObterOuCriarPacks() {
  const packs = {};
  for (const [chave, def] of Object.entries(NAUREN_PACKS_DEFINICAO)) {
    let pack = game.packs.find(p => p.metadata.label === def.label && p.metadata.type === def.type);
    if (!pack) {
      console.log(`Nauren RPG | Criando compêndio "${def.label}"...`);
      const dadosCriacao = { type: def.type, label: def.label };
      if (def.apenasMestre) dadosCriacao.ownership = NAUREN_OWNERSHIP_APENAS_MESTRE;
      pack = await (foundry.documents.collections?.CompendiumCollection ?? CompendiumCollection).createCompendium(dadosCriacao);
    } else if (def.apenasMestre && game.user.isGM) {
      try {
        await pack.configure({ ownership: NAUREN_OWNERSHIP_APENAS_MESTRE });
        // "pack.visible" não serve pra confirmar isso - é sempre true
        // pro próprio GM (que vê tudo), independente da ownership
        // configurada pra outros. O que de fato prova que a restrição
        // persistiu é comparar "ownership.PLAYER" (que os jogadores
        // usam) contra o valor esperado.
        if (pack.ownership?.PLAYER !== NAUREN_OWNERSHIP_APENAS_MESTRE.PLAYER) {
          console.warn(`Nauren RPG | "${def.label}" ainda aparece como visível pra não-Mestre depois de tentar restringir automaticamente (bug conhecido do Foundry V13, issue #13283) - restrinja manualmente: clique-direito no compêndio na barra lateral → "Toggle Visibility".`);
        }
      } catch (err) {
        console.warn(`Nauren RPG | Não consegui restringir "${def.label}" automaticamente - restrinja manualmente: clique-direito no compêndio na barra lateral → "Toggle Visibility".`, err);
      }
    }
    packs[chave] = pack;
  }
  return packs;
}

/**
 * Cria um item dentro de um pack SE ainda não existir um com o mesmo
 * "seedId" (gravado em flags.nauren.seedId) - devolve o item (recém-
 * criado ou já existente), permitindo referenciar o UUID dele depois
 * (ex: uma Classe apontando pra uma Habilidade concedida por ela).
 */
/**
 * Caminho da imagem de fundo padrão de uma árvore de Subclasse, seguindo
 * a convenção documentada em "assets/subclasses/README.md" - um arquivo
 * por classe, nome em minúsculo batendo com o "classeIdentifier". Se o
 * arquivo ainda não existir no mundo (ninguém colocou a arte lá ainda), o
 * navegador mostra uma imagem quebrada, mas o CSS tem uma altura mínima
 * de segurança (".nauren-subclasse-imagem-fundo") pra não deixar a árvore
 * pior do que ficaria sem imagem nenhuma - é seguro deixar isso sempre
 * ligado, mesmo antes de qualquer arte existir.
 */
/** O fundo da subclasse foi escolhido pelo Mestre (não é o caminho de fábrica)? */
function naurenFundoPersonalizado(caminho) {
  return !!caminho && !/systems\/nauren\/assets\/subclasses\/[^/]+$/.test(String(caminho));
}

/**
 * Fundo de subclasse que não carregou: tenta variações do nome do arquivo (maiúsculas,
 * acento, extensão). No Windows o nome não diferencia maiúsculas; num servidor (Forge) sim -
 * "Mago.png" enviado não abre como "mago.png". Usa a primeira variação que existir.
 */
document.addEventListener("error", ev => {
  const img = ev.target;
  if (!(img instanceof HTMLImageElement) || !img.classList.contains("nauren-subclasse-imagem-fundo")) return;
  const original = img.dataset.naurenOriginal || img.getAttribute("src") || "";
  const m = original.match(/^(.*\/)([^/]+?)\.(\w+)$/);
  if (!m) return;
  if (!img.dataset.naurenVariacoes) {
    const [, dir, base, ext] = m;
    const acentos = { mistico: "místico", empireo: "empíreo", cacador: "caçador" };
    const semAcento = base.toLowerCase();
    const comAcento = acentos[semAcento];
    const nomes = [...new Set([base, semAcento, semAcento.charAt(0).toUpperCase() + semAcento.slice(1), base.toUpperCase(),
      ...(comAcento ? [comAcento, comAcento.charAt(0).toUpperCase() + comAcento.slice(1)] : [])])];
    const exts = [...new Set([ext, "png", "webp", "jpg", "jpeg", "PNG", "WEBP", "JPG"])];
    const lista = [];
    for (const n of nomes) for (const e of exts) { const c = `${dir}${n}.${e}`; if (c !== original) lista.push(c); }
    img.dataset.naurenOriginal = original;
    img.dataset.naurenVariacoes = JSON.stringify(lista);
  }
  const resto = JSON.parse(img.dataset.naurenVariacoes);
  if (!resto.length) return;
  img.src = resto.shift();
  img.dataset.naurenVariacoes = JSON.stringify(resto);
}, true);

function naurenCaminhoImagemSubclasse(classeIdentifier) {
  return `systems/nauren/assets/subclasses/${classeIdentifier}.png`;
}

async function naurenGarantirItemNoPack(pack, seedId, dados) {
  dados = naurenFixarTipoAlcanceSemeado(foundry.utils.deepClone(dados));
  // Classe: equipamento recomendado do livro, se a definição não trouxer outro.
  if (dados?.type === "classe" && dados.system && !naurenEquipRecomendadoPreenchido(dados.system.equipamentoRecomendado)) {
    const padrao = NAUREN_EQUIPAMENTO_CLASSE_LIVRO[dados.system.identifier];
    if (padrao) dados.system.equipamentoRecomendado = foundry.utils.deepClone(padrao);
  }
  const chaveCapSeed = NAUREN_CAPACIDADE_POR_NOME?.[dados?.name];
  if (chaveCapSeed && ["habilidade", "condicao", "efeito"].includes(dados.type)) {
    dados = { ...dados, system: { ...(dados.system ?? {}), capacidades: [...new Set([...(dados.system?.capacidades ?? []), chaveCapSeed])] } };
  }
  await pack.getIndex({ fields: ["flags.nauren.seedId"] });
  const existente = pack.index.find(i => i.flags?.nauren?.seedId === seedId);
  if (existente) {
    // Bug real corrigido (achado num teste ao vivo do usuário): o item já
    // existente no compêndio NUNCA era atualizado - só era retornado como
    // estava, "congelado" pra sempre na versão de quando foi criado pela
    // primeira vez. Qualquer correção feita DEPOIS na definição desta
    // Habilidade/Magia/Efeito/Condição (aqui no código) nunca chegava ao
    // compêndio real de ninguém que já tivesse aberto o mundo antes -
    // "usaPerguntaAtaqueNoTurno" (Canalizar o Espírito, Tinta Celestial,
    // Chute do Nascer do Sol) é um exemplo, mas isso vale pra qualquer
    // campo de qualquer item já semeado antes da correção existir.
    // Agora SEMPRE atualiza com os dados mais recentes - o compêndio é a
    // fonte/molde (sem "rank investido"/"usos gastos" de personagem
    // nenhum), então isso é seguro; cópias já concedidas a atores têm seu
    // próprio botão "Atualizar item" (Ressincronizar com o Compêndio) pra
    // buscar essa versão nova quando o jogador quiser.
    const doc = await pack.getDocument(existente._id);
    if (!dados.type || doc.type === dados.type) {
      const novo = foundry.utils.deepClone(dados);
      // Fundo de subclasse escolhido pelo Mestre: não volta para o de fábrica a cada abertura do mundo.
      if (naurenFundoPersonalizado(doc.system?.imagemFundo) && novo.system) delete novo.system.imagemFundo;
      // Equipamento recomendado já configurado na Classe (pelo Mestre ou numa abertura anterior): não volta ao padrão.
      if (doc.type === "classe" && novo.system && naurenEquipRecomendadoPreenchido(doc.system?.equipamentoRecomendado)) delete novo.system.equipamentoRecomendado;
      await doc.update(novo);
      return doc;
    }
    // O item antigo era de outro tipo (ex.: magia -> habilidade): o Foundry não
    // deixa trocar o tipo. Aposenta o antigo (fica no compêndio, sem o seed) e
    // cria um novo no lugar.
    await doc.update({ name: /^\[(Removida|Fora de uso)/.test(String(doc.name)) ? doc.name : `[Fora de uso] ${doc.name}`, "flags.nauren.seedId": `${seedId}--antigo-${doc.type}` });
    console.log(`Nauren RPG | Compêndio "${pack.metadata.label}": "${doc.name}" era ${doc.type}; criado um novo como ${dados.type}.`);
  }

  const dadosCompletos = foundry.utils.mergeObject(
    foundry.utils.deepClone(dados),
    { flags: { nauren: { seedId } } }
  );
  const [criado] = await pack.documentClass.createDocuments([dadosCompletos], { pack: pack.collection });
  console.log(`Nauren RPG | Compêndio "${pack.metadata.label}": criado "${dados.name}".`);
  return criado;
}

/**
 * Mesma coisa que naurenGarantirItemNoPack, mas pra Habilidades de
 * Subclasse especificamente - marca "system.origem = 'subclasse'"
 * automaticamente, sem precisar lembrar disso em cada uma das ~170
 * chamadas espalhadas pelas funções de Subclasse. Essencial pra
 * "Subclasse" aparecer na ficha em Habilidades 100% passivas (sem
 * nenhuma Ação) - ver campo "origem" no schema e o uso dele no template.
 */
async function naurenGarantirHabilidadeDeSubclasse(pack, seedId, dados) {
  const dadosComOrigem = foundry.utils.mergeObject(
    foundry.utils.deepClone(dados),
    { system: { origem: "subclasse" } }
  );
  return naurenGarantirItemNoPack(pack, seedId, dadosComOrigem);
}

/** Mesma coisa, mas pra Habilidades de CLASSE (base) - marca "system.origem = 'classe'". */
async function naurenGarantirHabilidadeDeClasse(pack, seedId, dados) {
  const dadosComOrigem = foundry.utils.mergeObject(
    foundry.utils.deepClone(dados),
    { system: { origem: "classe" } }
  );
  return naurenGarantirItemNoPack(pack, seedId, dadosComOrigem);
}

/**
 * Mesma coisa que naurenGarantirHabilidadeDeSubclasse/naurenGarantirHabilidadeDeClasse,
 * mas pra itens do tipo Efeito - usado quando um nó de Subclasse/Classe
 * concede um Efeito diretamente (ex: os 5 Efeitos de Guarda do
 * Guerreiro, ou um Efeito-modificador de "modificadoresExternos" de uma
 * Subclasse nova) - marca "system.origem" pra aparecer na aba Efeitos da
 * ficha, mesmo padrão visual da aba Habilidades.
 */
async function naurenGarantirEfeitoDeSubclasse(pack, seedId, dados) {
  const dadosComOrigem = foundry.utils.mergeObject(foundry.utils.deepClone(dados), { system: { origem: "subclasse" } });
  return naurenGarantirItemNoPack(pack, seedId, dadosComOrigem);
}
async function naurenGarantirEfeitoDeClasse(pack, seedId, dados) {
  const dadosComOrigem = foundry.utils.mergeObject(foundry.utils.deepClone(dados), { system: { origem: "classe" } });
  return naurenGarantirItemNoPack(pack, seedId, dadosComOrigem);
}

/**
 * Busca os UUIDs de vários itens de um pack de uma vez, pelos seedIds
 * deles - usado pra montar pools de itens (ex: "Escolha de Itens" no
 * nível 1 de toda Classe, ver naurenSemearClasses) sem precisar buscar
 * um por um. Ignora silenciosamente qualquer seedId não encontrado
 * (nunca deveria acontecer se chamado DEPOIS do pack já ter sido
 * semeado, mas não trava a inicialização inteira se acontecer).
 */
async function naurenBuscarUuidsDoPack(pack, seedIds) {
  await pack.getIndex({ fields: ["flags.nauren.seedId"] });
  const uuids = [];
  for (const seedId of seedIds) {
    const entrada = pack.index.find(i => i.flags?.nauren?.seedId === seedId);
    if (!entrada) {
      console.warn(`Nauren RPG | naurenBuscarUuidsDoPack: seedId "${seedId}" não encontrado em "${pack.metadata.label}".`);
      continue;
    }
    const doc = await pack.getDocument(entrada._id);
    uuids.push({ uuid: doc.uuid });
  }
  return uuids;
}

