/** Semeia o item de Classe do Mago, concedendo cada Página do Grimório no nível correspondente. */
async function naurenSemearClasseMago(pack, uuidGrimorio, uuidDarPrioridade, packMagias, packHabilidades) {
  async function buscarMagiaUuid(seedId) {
    await packMagias.getIndex({ fields: ["flags.nauren.seedId"] });
    const entrada = packMagias.index.find(i => i.flags?.nauren?.seedId === seedId);
    if (!entrada) return "";
    const doc = await packMagias.getDocument(entrada._id);
    return doc.uuid;
  }
  const paginas = {};
  // Tabela número da página -> seedId (acrescentar aqui quando o livro trouxer magias novas).
  const seedIdPorPagina = {
      1: "magia-pagina-1-misseis-arcanos", 2: "magia-pagina-2-escudo-de-mana", 3: "magia-pagina-3-retardo-temporal",
      4: "magia-pagina-4-salto-eterio", 5: "magia-pagina-5-anular-magia", 6: "magia-pagina-6-polimorfia",
      7: "magia-pagina-7-criar-comida-bebida", 8: "magia-pagina-8-queda-lenta", 9: "magia-pagina-9-chuva-de-estrelas",
      10: "magia-pagina-10-pressao-gravitacional", 11: "magia-pagina-11-mao-dispersora", 12: "magia-pagina-12-invisibilidade",
      13: "magia-pagina-13-bola-de-fogo", 14: "magia-pagina-14-consertar", 15: "magia-pagina-15-portal",
      16: "magia-pagina-16-implosao-arcana", 17: "magia-pagina-17-conjurar-objeto", 18: "magia-pagina-18-terra-magica",
      19: "magia-pagina-19-paralisia-mental", 20: "magia-pagina-20-conjurar-pequeno-mundo",
      21: "magia-pagina-21-conjurar-espada-lunar", 22: "magia-pagina-22-bomba-cronometrada", 23: "magia-pagina-23-estouro-de-magma",
      24: "magia-pagina-24-espadas-cristal-boreal", 25: "magia-pagina-25-arco-glacial-lazuli",
      26: "magia-pagina-26-raio-dourado-topazio", 27: "magia-pagina-27-levitar"
  };
  const totalPaginas = Math.max(...Object.keys(seedIdPorPagina).map(Number));
  for (let n = 1; n <= totalPaginas; n++) {
    const seedId = seedIdPorPagina[n];
    paginas[n] = await buscarMagiaUuid(seedId);
  }

  // Lista de magias "escolhíveis livremente" (v0.7 do manual: cada nível
  // concede "1 Magia", à escolha do jogador, não uma página numerada
  // fixa) - as 20 válidas, SEM as 3 removidas (Consertar, Paralisia
  // Mental, Conjurar Pequeno Mundo, Implosão Arcana). Livro 0.7.1:
  // "Nível 1: Grimório do Mago, e 1 Magia" - a magia inicial também é
  // escolhida (Mísseis Arcanos entra na lista).
  const seedIdsRemovidas = new Set([14, 16, 19, 20]); // fora da lista do livro 0.7.1
  const todasAsMagiasEscolhiveis = [];
  for (let n = 1; n <= totalPaginas; n++) {
    if (seedIdsRemovidas.has(n)) continue;
    if (paginas[n]) todasAsMagiasEscolhiveis.push({ uuid: paginas[n] });
  }

  const uuidSendoUmMago = await naurenSemearHabilidadeSendoUmMago(packHabilidades);
  const uuidCondensarMagia = await naurenSemearHabilidadeCondensarMagia(packHabilidades);
  // Escolha de "1 Magia" (v0.7 do manual) - mesma entrada reaproveitada
  // em todo nível 2-20 (exceto 5, Subclasse), já filtrada pra nunca
  // repetir uma magia que o Ator já tenha (ver _popupEscolhaItens).
  const escolhaUmaMagia = { ativo: true, itensDisponiveis: todasAsMagiasEscolhiveis, quantidadeEscolhas: "1" };

  await naurenGarantirItemNoPack(pack, "classe-mago", {
    name: "Mago", type: "classe", img: "icons/skills/trades/academics-book-study-purple.webp",
    system: {
      identifier: "mago",
      descricao: "<p>O Mago é a mente que dobra o impossível. Seu Grimório é mais que um livro - é uma extensão da alma, onde cada página contém um fragmento de sua compreensão sobre o mundo. Controlar o Grimório é controlar o caos.</p>",
      niveis: [
        { nivel: 1, itensConcedidos: [{ uuid: uuidGrimorio }, { uuid: uuidSendoUmMago }, { uuid: uuidDarPrioridade }], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 2, itensConcedidos: [{ uuid: uuidCondensarMagia }], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 3, itensConcedidos: [], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 4, itensConcedidos: [], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 5, itensConcedidos: [], upgradesDeRank: [] },
        { nivel: 6, itensConcedidos: [], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 7, itensConcedidos: [], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 8, itensConcedidos: [], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 9, itensConcedidos: [], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 10, itensConcedidos: [], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 11, itensConcedidos: [], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 12, itensConcedidos: [], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 13, itensConcedidos: [], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 14, itensConcedidos: [], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 15, itensConcedidos: [], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 16, itensConcedidos: [], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 17, itensConcedidos: [], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 18, itensConcedidos: [], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 19, itensConcedidos: [], upgradesDeRank: [], escolhaItens: escolhaUmaMagia },
        { nivel: 20, itensConcedidos: [], upgradesDeRank: [], escolhaItens: escolhaUmaMagia }
      ]
    }
  });
}





