    nos.push({ id: "adentrar-o-infinito", x: 37.6, y: 91.05, largura: 7.1, altura: 5.0, nome: "Adentrar o Infinito", tipo: "Habilidade Ativa", rankMax: 3, itemUuid: it.uuid, prerequisitos: [{ id: "empoderamento-estelar", linhaVisivel: false }, { id: "explosao-purpura", linhaVisivel: false }] });
