      rankMax: 3, apenasUpgrade: true, itemUuid: uuidComungar,
      modificadores: [{ itemAlvoUuid: uuidComungar, campo: "acoes.1.gastosRecurso.0.quantidade", modo: "substituir", valorPorRank: [{ rank: 1, valor: "-1d6-1" }, { rank: 2, valor: "-1d6-2" }, { rank: 3, valor: "-1d6-3" }] }],
