/**
 * Junta as 3 Subclasses do Druida (Restauradores, Andarilhos das Peles,
 * Crescimento) NUM ÚNICO item de Subclasse, já que a arte de referência
 * (druida_1.png) mostra as 3 juntas numa imagem só - um item por
 * subclasse duplicaria a mesma imagem de fundo e só mostraria 1/3 dos
 * nós clicáveis em cada. As posições Y de cada função já foram
 * desenhadas pra caber juntas na MESMA imagem, sem sobrepor.
 */
async function naurenSemearSubclasseDruida(pack, packHabilidades, packCondicoes) {
  const nosRestauradores = await naurenSemearSubclasseDruidaRestauradores(pack, packHabilidades, packCondicoes);
  const nosAndarilhos = await naurenSemearSubclasseDruidaAndarilhosDasPeles(pack, packHabilidades, packCondicoes);
  const nosCrescimento = await naurenSemearSubclasseDruidaCrescimento(pack, packHabilidades, packCondicoes);

  // Ajuste tardio do Oásis Verdejante (Restauradores): Santuário Selvagem
  // só existe a partir daqui (é semeado por naurenSemearSubclasseDruidaCrescimento,
  // ACIMA - Restauradores roda primeiro e não tinha esse UUID disponível
  // quando montou seus próprios gatilhos). Busca de novo agora que os 3
  // já foram semeados, e completa a lista se ainda não tiver essa entrada
  // (checa por "itemAlvoUuid" pra nunca duplicar em reprocessamentos).
  await packHabilidades.getIndex({ fields: ["flags.nauren.seedId"] });
  const entradaSantuario = packHabilidades.index.find(i => i.flags?.nauren?.seedId === "habilidade-druida-santuario-selvagem");
  const entradaOasis = packHabilidades.index.find(i => i.flags?.nauren?.seedId === "habilidade-druida-oasis-verdejante");
  if (entradaSantuario && entradaOasis) {
    const uuidSantuarioSelvagem = (await packHabilidades.getDocument(entradaSantuario._id)).uuid;
    const docOasis = await packHabilidades.getDocument(entradaOasis._id);
    const jaTem = (docOasis.system.gatilhosTemplatePersistente ?? []).some(g => g.itemAlvoUuid === uuidSantuarioSelvagem);
    if (!jaTem) {
      const gatilhosCompletos = [
        ...docOasis.system.gatilhosTemplatePersistente,
        { itemAlvoUuid: uuidSantuarioSelvagem, evento: "aoEntrar", disposicao: "inimigos", efeito: "", quantidade: "1", condicaoUuid: docOasis.system.gatilhosTemplatePersistente[0]?.condicaoUuid ?? "", condicaoAcumulos: "1" }
      ];
      await docOasis.update({
        "system.gatilhosTemplatePersistente": gatilhosCompletos
      });
    }
  }

  await naurenGarantirItemNoPack(pack, "subclasse-druida", {
    name: "Druida — Subclasses", type: "subclasse", img: "icons/magic/nature/leaf-armor-scale-green.webp",
    system: {
      identifier: "druida-subclasses", classeIdentifier: "druida",
      descricao: "<p>As 3 vias do Druida, sobre a mesma árvore: <b>Restauradores</b> (topo) - guardiões de vida que curam aliados aos poucos. <b>Andarilhos das Peles</b> (meio) - metamorfose em formas de besta. <b>Crescimento</b> (base) - poder que se acumula rodada a rodada em combate.</p>",
      imagemFundo: naurenCaminhoImagemSubclasse("druida"), zoomFundo: 100,
      nos: [...nosRestauradores, ...nosAndarilhos, ...nosCrescimento]
    }
  });
}

