/**
 * Junta as 3 Subclasses do Ladino (Ardiloso, Oportunista, Egoísta) NUM
 * ÚNICO item, mesmo padrão das outras classes - a árvore tem estrutura
 * IRREGULAR (12+6+10=28 nós, fileiras de tamanho variável), diferente da
 * grade 3x3 limpa de Druida/Guerreiro/Empíreo.
 */
async function naurenSemearSubclasseLadino(pack, packHabilidades, packCondicoes, h, armasModelo = {}) {
  const nosArdiloso = await naurenSemearSubclasseLadinoArdiloso(pack, packHabilidades, packCondicoes, armasModelo);
  const nosOportunista = await naurenSemearSubclasseLadinoOportunista(pack, packHabilidades, packCondicoes, h.analisePaciente, armasModelo);
  const nosEgoista = await naurenSemearSubclasseLadinoEgoista(pack, packHabilidades, packCondicoes, h.invisivelNoCaos);

  await naurenGarantirItemNoPack(pack, "subclasse-ladino", {
    name: "Ladino — Subclasses", type: "subclasse", img: "icons/skills/melee/strike-dagger-skull-white.webp",
    system: {
      identifier: "ladino-subclasses", classeIdentifier: "ladino",
      descricao: "<p>As 3 vias do Ladino, sobre a mesma árvore: <b>Ardiloso</b> (topo) - manipulação, sangramento e mentiras. <b>Oportunista</b> (meio) - precisão cirúrgica baseada em informação (Análise Paciente/Estudado). <b>Egoísta</b> (base) - rouba recursos, prioridade e sorte de aliados e inimigos.</p>",
      imagemFundo: naurenCaminhoImagemSubclasse("ladino"), zoomFundo: 100,
      nos: [...nosArdiloso, ...nosOportunista, ...nosEgoista]
    }
  });
}
