      gatilhos: [{ evento: "inicioCombate", recurso: "recursoCustom:energia", quantidade: "@herancasDeCor+max(@rank,1)-1" }], // rank 0 conta como 1
      descricao: naurenMontarDescricao({ regra: "Passiva. Ao iniciar uma cena de combate, ganhe 1 Energia para cada Herança de Cor que possua (rank 1), +1 Energia adicional por rank (até 3).", automatico: "no início do combate: Energia = suas Heranças de Cor + (rank − 1).", manual: "" })
