// 0.94.27: itens que saíram da loja (os Refinados). O compêndio apaga; as cópias nas fichas ficam e o Export Data
// continua reconhecendo a chave (retiradoDoCatalogo: true).
const NAUREN_TORRE_RETIRADOS = {"adaga-carmim": {"nome": "Adaga Carmim", "tier": "Bronze", "pigmento": "Vermelho"}, "martelo-brasa-viva": {"nome": "Martelo Brasa-Viva", "tier": "Ouro", "pigmento": "Vermelho"}, "robe-mare-mansa": {"nome": "Robe da Maré Mansa", "tier": "Bronze", "pigmento": "Azul"}, "varinha-abissal": {"nome": "Varinha Abissal", "tier": "Ouro", "pigmento": "Azul"}, "couro-de-musgo": {"nome": "Couro de Musgo", "tier": "Bronze", "pigmento": "Verde"}, "escudo-raiz-mae": {"nome": "Escudo da Raiz-Mãe", "tier": "Ouro", "pigmento": "Verde"}, "botas-gato-violeta": {"nome": "Botas do Gato Violeta", "tier": "Bronze", "pigmento": "Roxo"}, "capa-do-enigma": {"nome": "Capa do Enigma", "tier": "Ouro", "pigmento": "Roxo"}, "gibao-fuliginoso": {"nome": "Gibão Fuliginoso", "tier": "Bronze", "pigmento": "Preto"}, "placa-de-breu": {"nome": "Placa de Breu", "tier": "Ouro", "pigmento": "Preto"}, "escudo-ordem-alva": {"nome": "Escudo da Ordem Alva", "tier": "Bronze", "pigmento": "Branco"}, "cota-aurora-alva": {"nome": "Cota da Aurora Alva", "tier": "Ouro", "pigmento": "Branco"}, "sapatilhas-de-petala": {"nome": "Sapatilhas de Pétala", "tier": "Bronze", "pigmento": "Rosa"}, "capa-brisa-rosada": {"nome": "Capa da Brisa Rosada", "tier": "Ouro", "pigmento": "Rosa"}, "robe-peregrino-aureo": {"nome": "Robe do Peregrino Áureo", "tier": "Bronze", "pigmento": "Dourado"}, "manto-sol-poente": {"nome": "Manto do Sol Poente", "tier": "Ouro", "pigmento": "Dourado"}};
const NAUREN_TORRE_NOTAS = {
  tonico: "Máximo 1 Tônico por rodada: o limite automático é por item; confira se nenhum outro Tônico foi usado na mesma rodada."
};

// Valores EXATOS do bot O Curador (o rótulo é só o que aparece na tela).
const NAUREN_TORRE_TIERS = { "": "Sem tier (qualquer um usa)", Bronze: "Bronze", Prata: "Prata", Ouro: "Ouro", Diamante: "Diamante", Prismatico: "Prismático" };
const NAUREN_TORRE_RARIDADES = { basico: "Básico (comum)", consumivel: "Consumível", refinado: "Refinado", magico: "Mágico", falsario: "Falsário" };
const NAUREN_TORRE_LOJAS = { galeria: "Galeria", falsarios: "Falsários" };
const NAUREN_TORRE_PIGMENTOS = { "": "Sem pigmento", Vermelho: "Vermelho", Azul: "Azul", Verde: "Verde", Roxo: "Roxo", Preto: "Preto", Branco: "Branco", Rosa: "Rosa", Dourado: "Dourado" };
/** Selo do tier de um item da Torre: { rotulo, classe } ou null. */
function naurenTierTorre(item) {
  const t = item?.flags?.nauren?.torre ?? item?.getFlag?.("nauren", "torre");
  if (!t) return null;
  const tier = t.tier || "";
  return { rotulo: tier ? (NAUREN_TORRE_TIERS[tier] ?? tier) : "Sem tier", classe: tier ? String(tier).toLowerCase() : "sem" };
}
// Sem tier / sem pigmento são gravados como null (o que o bot espera); preço sempre número.
Hooks.on("preUpdateItem", (item, changes) => {
  const t = changes?.flags?.nauren?.torre;
  if (!t || typeof t !== "object") return;
  if ("tier" in t && !t.tier) t.tier = null;
  if ("pigmento" in t && !t.pigmento) t.pigmento = null;
  if ("preco" in t) t.preco = Math.max(0, Math.round(Number(t.preco) || 0));
  if ("chave" in t) t.chave = String(t.chave ?? "").trim();
});

function naurenTorreTransformarAcao(a, t) {
  if (!t) return a;
  const n = foundry.utils.deepClone(a);
  const mexerDanos = fn => { n.danos = (n.danos ?? []).map(d => ({ ...d, formula: fn(String(d.formula ?? "")) })); };
  if (t.dadoGariart && /gariart/i.test(n.nome ?? "")) mexerDanos(f => f.replace(/\d+d4/, t.dadoGariart));
  if (t.maisDado && n.ehAtaque) mexerDanos(f => f.replace(/(\d+)d(\d+)/, (m, q, d) => `${Number(q) + 1}d${d}`));
  if (t.dadoFixo && n.ehAtaque) { const lado = t.dadoFixo.split("d")[1]; mexerDanos(f => f.replace(/(\d+)d\d+/, (m, q) => `${q}d${lado}`)); }
  if (t.critMinAjuste && n.ehAtaque) n.critMinAjuste = t.critMinAjuste;
  return n;
}

/**
 * 0.94.24: parágrafo "Como usar" de todo item da Torre, montado das próprias Ações (custo, limite,
 * alcance, quando dá para usar) - o jogador não precisa adivinhar onde clicar.
 */
function naurenTorreComoUsar(spec) {
  const partes = [];
  const equipa = spec.tipo === "arma" || spec.tipo === "armadura";
  if (equipa) partes.push("Equipe o item na ficha (Inventário). Os atributos e as passivas valem enquanto ele estiver equipado.");
  if (spec.tipo === "consumivel") partes.push("Use pelo Inventário ou pelo HUD de combate: cada uso gasta 1 unidade.");
  const usosTxt = { cena: "1 vez por cena", rodada: "1 vez por rodada", turno: "1 vez por turno", combate: "1 vez por combate", descanso: "1 vez por descanso" };
  for (const a of spec.acoes ?? []) {
    const custo = [a.custoEstamina ? `${a.custoEstamina} Estamina` : "", a.custoMana ? `${a.custoMana} Mana` : ""].filter(Boolean).join(" + ") || "sem custo";
    const lim = a.usosMax ? (a.usosMax === 1 ? usosTxt[a.usosReset] ?? `1 vez (${a.usosReset})` : `${a.usosMax} vezes (${a.usosReset})`) : "";
    const alvo = a.modoAlvo === "area" ? (a.areaDisposicao === "aliados" ? "coloque a área no mapa (atinge você e aliados)" : "coloque a área no mapa (atinge só inimigos; cada um pode reagir)")
      : a.modoAlvo === "selecionado" ? `marque o alvo com T${a.alcance && a.alcance !== "pessoal" ? ` (até ${a.alcance})` : ""}` : "";
    const prio = a.prioridadeUso === "tambem" || a._naPrioridade ? " Pode ser usada na sua Prioridade (junto da reação)." : "";
    partes.push(`<b>${a.nome}</b>: clique na Ação no item (ou no HUD de combate)${alvo ? ` e ${alvo}` : ""}. Custa ${custo}${lim ? `, ${lim}` : ""}.${prio}`);
  }
  if (spec.comoUsarExtra) partes.push(spec.comoUsarExtra);
  if (!partes.length) return "";
  return `<p><b>Como usar</b></p><ul>${partes.map(x => `<li>${x}</li>`).join("")}</ul><p><i>Tudo é automático: custo, limite de usos, dano, cura, Condições e duração aparecem no card do chat.</i></p>`;
}

async function naurenSemearTorre(packs) {
  const pack = packs.torre;
  if (!pack) return;
  const existentes = await pack.getDocuments();
  const porChave = k => existentes.find(d => d.getFlag("nauren", "torre")?.chave === k);
  const porCond = k => existentes.find(d => d.getFlag("nauren", "torreCond") === k);
  const retiradosNoPack = existentes.filter(d => NAUREN_TORRE_RETIRADOS[d.getFlag("nauren", "torre")?.chave]);
  if (retiradosNoPack.length) await getDocumentClass("Item").deleteDocuments(retiradosNoPack.map(d => d.id), { pack: pack.collection }).catch(err => console.warn("Nauren RPG | Torre: falha ao tirar itens retirados.", err));
  const tudoEmDia = NAUREN_TORRE.itens.every(i => porChave(i.chave)?.getFlag("nauren", "torreVersao") === NAUREN_TORRE_VERSAO)
    && Object.keys(NAUREN_TORRE.conds).every(k => porCond(k)?.getFlag("nauren", "torreVersao") === NAUREN_TORRE_VERSAO);
  if (tudoEmDia) return;

  // Pastas (as do catálogo + uma para as Condições usadas pelos itens).
  const PASTA_CONDICOES = "Efeitos dos itens (Condições)";
  const pastas = {};
  for (const nome of [...new Set(NAUREN_TORRE.itens.map(i => i.pasta)), PASTA_CONDICOES]) {
    let f = pack.folders.find(x => x.name === nome);
    if (!f) f = await getDocumentClass("Folder").create({ name: nome, type: "Item", sorting: "a" }, { pack: pack.collection });
    pastas[nome] = f.id;
  }
  const Item = getDocumentClass("Item");
  const packCond = packs.condicoes; await packCond.getIndex();
  const uuidSistema = nome => { const e = packCond.index.find(x => x.name === nome); return e ? `Compendium.${packCond.collection}.Item.${e._id}` : ""; };
  const uuidTorre = {};
  const resolver = v => {
    if (typeof v === "string") {
      if (v.startsWith("sys:")) return uuidSistema(v.slice(4));
      if (v.startsWith("torre:")) return uuidTorre[v.slice(6)] ?? "";
      return v;
    }
    if (Array.isArray(v)) return v.map(resolver);
    if (v && typeof v === "object") return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, resolver(x)]));
    return v;
  };

  // 1) Condições
  for (const [chave, dadosOrig] of Object.entries(NAUREN_TORRE.conds)) {
    const d = foundry.utils.deepClone(dadosOrig);
    const clonar = d.system._clonarSistema; delete d.system._clonarSistema;
    if (clonar) {
      const e = packCond.index.find(x => x.name === clonar);
      if (e) d.system = foundry.utils.mergeObject((await packCond.getDocument(e._id)).toObject().system, d.system, { inplace: false });
    }
    d.system = resolver(d.system);
    const dadosDoc = { name: d.name, type: d.type === "efeito" ? "efeito" : "condicao", img: d.img, system: d.system, folder: pastas[PASTA_CONDICOES],
      flags: { nauren: { torreCond: chave, torreVersao: NAUREN_TORRE_VERSAO } } };
    const ex = porCond(chave);
    const doc = ex ? (await ex.update(dadosDoc), ex) : await Item.create(dadosDoc, { pack: pack.collection });
    uuidTorre[chave] = doc.uuid;
  }

  // 2) Itens
  for (const spec of NAUREN_TORRE.itens) {
    let base = null;
    if (spec.base) {
      const pk = packs[spec.base[0]];
      await pk.getIndex();
      const e = pk.index.find(x => x.name === spec.base[1]);
      if (e) base = (await pk.getDocument(e._id)).toObject();
      else console.warn(`Nauren RPG | Torre: base "${spec.base[1]}" não encontrada para "${spec.nome}".`);
    }
    const system = base ? foundry.utils.deepClone(base.system) : {};
    Object.assign(system, spec.sistema);
    if (spec.efeitos?.length) system.efeitosVinculados = [...(system.efeitosVinculados ?? []), ...spec.efeitos];
    // 0.94.24: limite de usos de verdade - "usosMax" sem "usaUsos" não travava nada (o item dizia 1/cena e deixava usar à vontade).
    system.acoes = [...(system.acoes ?? []).map(a => naurenTorreTransformarAcao(a, spec.transformar)), ...spec.acoes.map(a => (a.usosMax > 0 && a.usaUsos === undefined) ? { ...a, usaUsos: true } : a)];
    if ("equipado" in system || spec.tipo !== "consumivel") system.equipado = false;
    if (spec.tipo === "consumivel" && !base) Object.assign(system, { quantidade: 1, quantidadeMax: 99, efeito: "", prioridadeIndicador: "PA" });
    const t = spec.flags?.nauren?.torre ?? {};
    const escolha = (spec.efeitos ?? []).filter(e => e.ativo === false).length > 0;
    const notas = (spec.nota ?? "").split(" ").map(k => NAUREN_TORRE_NOTAS[k]).filter(Boolean);
    if (spec.efeitosAoEquipar?.length) system.efeitosAoEquipar = [...(system.efeitosAoEquipar ?? []), ...spec.efeitosAoEquipar];
    // Preço 0 = o bot da Torre ainda vai definir: não aparece na descrição.
    // 0.94.27: sem preço na descrição - quem define o preço é o bot da Torre (O Curador).
    system.descricao = `<p><b>Torre Infinita</b> · ${t.tier ?? "sem tier"} · ${t.raridade ?? ""}</p>${spec.html ?? `<p>${spec.texto}</p>`}`
      + naurenTorreComoUsar(spec)
      + (escolha ? "<p><i>Bônus escolhido ao receber: ao colocar o item na ficha, uma janela pergunta qual. Para trocar depois: ficha do item → Efeitos vinculados (deixe só uma opção marcada).</i></p>" : "")
      + notas.map(n => `<p>${n}</p>`).join("");
    const flagsNauren = { torreVersao: NAUREN_TORRE_VERSAO };
    if (spec.escolha?.length) flagsNauren.escolhaAoReceber = { rotulos: spec.escolha, inicio: (system.efeitosVinculados?.length ?? 0) - spec.escolha.length };
    naurenFixarTipoAlcanceSemeado({ name: spec.nome, type: spec.tipo, system });
    const dadosDoc = {
      name: spec.nome, type: spec.tipo, img: spec.img || base?.img || "icons/svg/item-bag.svg",
      system: resolver(system), folder: pastas[spec.pasta],
      flags: foundry.utils.mergeObject(foundry.utils.deepClone(spec.flags), { nauren: flagsNauren })
    };
    const ex = porChave(spec.chave);
    if (ex) await ex.update(dadosDoc);
    else await Item.create(dadosDoc, { pack: pack.collection });
  }
  console.log(`Nauren RPG | Itens da Torre Infinita prontos (versão ${NAUREN_TORRE_VERSAO}, ${NAUREN_TORRE.itens.length} itens).`);
}

/** Escudo com duração ("até o fim da rodada", "N rodadas"): some quando a rodada passa ou o combate acaba. */
async function naurenExpirarEscudo(actor, combat, forcar = false) {
  const e = actor?.getFlag?.("nauren", "escudoExpira");
  if (!e) return;
  // 0.94.24: "até o início do próximo turno de quem usou" (turnoDe = combatente de quem usou).
  const venceu = forcar || !combat || e.combate !== combat.id || (e.turnoDe && combat.combatants?.get?.(e.turnoDe)
    ? (combat.combatant?.id === e.turnoDe && ((combat.round ?? 0) > (e.rodada ?? 0) || ((combat.round ?? 0) === (e.rodada ?? 0) && (combat.turn ?? 0) > (e.turno ?? 0))))
    : (combat.round ?? 0) > (e.rodada ?? 0));
  if (!venceu) return;
  const tinha = actor.system.escudo?.value ?? 0;
  // Sustentar (Escudo de Mana: "pode ser sustentada com 1 Mana no início de cada rodada"): pergunta ao dono.
  if (!forcar && combat && e.combate === combat.id && e.sustentar?.recurso && tinha > 0) {
    const qtd = Math.round(naurenInterpretarModificador(String(e.sustentar.quantidade || "1"), actor)?.valor ?? 1);
    const nomeRec = naurenNomeDoRecurso(null, e.sustentar.recurso);
    const tem = naurenAtorTemRecurso(actor, e.sustentar.recurso, qtd);
    const sustentou = tem && await NaurenAlvoHelper.perguntarSustentar(actor, { nomeRegiao: `${e.sustentar.nome} (escudo: ${tinha})`, recurso: e.sustentar.recurso, quantidade: qtd });
    if (sustentou) {
      await NaurenAlvoHelper._aplicarRecursoNoAlvo(actor, e.sustentar.recurso, qtd);
      await actor.setFlag("nauren", "escudoExpira", { ...e, rodada: combat.round });
      naurenPostarCard({ ator: actor, titulo: e.sustentar.nome, icone: "icons/magic/defensive/shield-barrier-blue.webp", fonte: "Sustentar",
        linhas: [{ label: "Escudo mantido", value: `${tinha}`, breakdown: `−${qtd} ${nomeRec} • até o fim da rodada ${combat.round}` }] });
      return;
    }
    if (!tem) {
      await actor.update({ "system.escudo.value": 0, "system.escudo.max": 0 });
      await actor.unsetFlag("nauren", "escudoExpira");
      naurenPostarCard({ ator: actor, titulo: "Escudo terminou", icone: "icons/magic/defensive/shield-barrier-blue.webp", linhas: [{ label: actor.name, value: `−${tinha} de escudo`, breakdown: `${e.sustentar.nome}: faltou ${qtd} de ${nomeRec} para sustentar` }] });
      return;
    }
  }
  await actor.update({ "system.escudo.value": 0, "system.escudo.max": 0 });
  await actor.unsetFlag("nauren", "escudoExpira");
  if (tinha > 0) naurenPostarCard({ ator: actor, titulo: "Escudo terminou", icone: "icons/magic/defensive/shield-barrier-blue.webp", linhas: [{ label: actor.name, value: `−${tinha} de escudo`, breakdown: "a duração acabou" }] });
}

/**
 * Item com bônus "escolhido ao receber" (flags.nauren.escolhaAoReceber = { rotulos, inicio }):
 * as opções são efeitos vinculados consecutivos a partir de "inicio"; a escolhida fica ativa, as outras não.
 * Genérico - qualquer item pode declarar opções assim.
 */
async function naurenPerguntarEscolhaAoReceber(item) {
  const esc = item.getFlag("nauren", "escolhaAoReceber");
  if (!esc?.rotulos?.length) return null;
  const escH = v => String(v).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
  let escolhido = null;
  await foundry.applications.api.DialogV2.wait({
    window: { title: `${item.name} · escolha o bônus` }, classes: ["nauren-janela-movimento"], position: { width: 380 },
    content: `<div class="nauren-mov"><p class="nauren-mov-aviso" style="margin:0;">Este item dá um bônus à sua escolha. Ele fica valendo enquanto o item estiver equipado.</p>
      <div class="nauren-mov-opcoes">${esc.rotulos.map((r, k) => `<button type="button" class="nauren-mov-opcao" data-escolha="${k}"><i class="fas fa-star"></i><span class="nauren-mov-titulo">${escH(r)}</span><span class="nauren-mov-custo"></span></button>`).join("")}</div></div>`,
    buttons: [{ action: "depois", label: "Escolher depois" }], rejectClose: false,
    render: (ev, dialog) => dialog.element.querySelectorAll(".nauren-mov-opcao").forEach(b => b.addEventListener("click", () => { escolhido = Number(b.dataset.escolha); dialog.close(); }))
  }).catch(() => null);
  if (escolhido === null) return null;
  const lista = foundry.utils.deepClone(item.system.efeitosVinculados ?? []);
  esc.rotulos.forEach((r, k) => { const e = lista[(esc.inicio ?? 0) + k]; if (e) e.ativo = k === escolhido; });
  await item.update({ "system.efeitosVinculados": lista, "flags.nauren.escolhaFeita": escolhido });
  ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: item.actor }), content: `<p><b>${escH(item.name)}</b>: bônus escolhido — ${escH(esc.rotulos[escolhido])}.</p>` });
  return escolhido;
}
Hooks.on("createItem", (item, options, userId) => {
  if (userId !== game.user.id || item.parent?.documentName !== "Actor") return;
  if (!item.getFlag("nauren", "escolhaAoReceber")?.rotulos?.length || item.getFlag("nauren", "escolhaFeita") !== undefined) return;
  naurenPerguntarEscolhaAoReceber(item).catch(err => console.warn("Nauren RPG | Falha na escolha ao receber.", err));
});

const naurenConsumiveisSaindo = new Set();
/**
 * Consumível que chegou a 0 sai da ficha - roda só na máquina de quem fez a mudança.
 * Fica se: configuração desligada, "Manter na ficha ao acabar", ou outro item o usa como
 * fonte de cargas/veneno (apagar quebraria a arma ou a Ação).
 */
Hooks.on("updateItem", (item, changes, options, userId) => {
  if (userId !== game.user.id || item.type !== "consumivel" || item.parent?.documentName !== "Actor") return;
  if (!foundry.utils.hasProperty(changes, "system.quantidade") || (item.system.quantidade ?? 0) > 0) return;
  if (!game.settings.get("nauren", "removerConsumivelZerado") || item.system.manterAoZerar) return;
  const actor = item.parent;
  const usadoPorOutro = actor.items.some(o => o.id !== item.id && (
    o.system?.venenoCargasConsumivelId === item.id
    || (o.system?.acoes ?? []).some(a => a.cargasFonte === "consumivel" && a.cargasConsumivelId === item.id)
  ));
  if (usadoPorOutro) return;
  // Duas atualizações seguidas a 0 (ex.: beber o último Frasco) não podem apagar e avisar duas vezes.
  if (naurenConsumiveisSaindo.has(item.uuid) || !actor.items.get(item.id)) return;
  naurenConsumiveisSaindo.add(item.uuid);
  const nome = item.name;
  actor.deleteEmbeddedDocuments("Item", [item.id]).finally(() => setTimeout(() => naurenConsumiveisSaindo.delete(item.uuid), 2000)).then(() => {
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor }), content: `<p class="nauren-aviso-chat"><i class="fas fa-box-open"></i> <b>${foundry.utils.escapeHTML?.(nome) ?? nome}</b> acabou e saiu da ficha.</p>`, whisper: [] });
  }).catch(err => console.warn("Nauren RPG | Falha ao remover consumível zerado.", err));
});

/** Dano de área persistente conta como "Eu dei dano" de quem criou a área (com o nome do item, para filtros). */
function naurenGatilhoDanoDeArea(atorOrigem, config, alvoActor) {
  if (!atorOrigem) return;
  let itemNome = "";
  try { itemNome = config?.origemItemUuid ? (fromUuidSync(config.origemItemUuid)?.name ?? "") : ""; } catch (err) { itemNome = ""; }
  naurenProcessarGatilhos("euDeiDano", atorOrigem, { itemUsadoUuid: config?.origemItemUuid ?? "", itemNome, alvoUuid: alvoActor?.uuid ?? "", origem: "areaPersistente" })
    .catch(err => console.warn("Nauren RPG | Falha ao processar gatilhos (dano de área).", err));
}

/** Campo numérico da janela de confirmação que aceita fórmula ("2", "1d4", "1d6+2", "-1d4"): rola e devolve o total. */
async function naurenRolarAjustePopup(texto, rotulo = "") {
  const t = String(texto ?? "").trim();
  if (!t || t === "0") return 0;
  if (!/\d*d\d+/i.test(t)) return Number(t) || 0;
  try {
    const roll = await new Roll(t).evaluate();
    if (game.dice3d) await game.dice3d.showForRoll(roll, game.user, true);
    if (rotulo) ui.notifications.info(`${rotulo}: ${t} = ${roll.total}`);
    return Math.round(roll.total);
  } catch (err) { console.warn("Nauren RPG | fórmula inválida na janela de confirmação", t, err); return Number(t) || 0; }
}

/** Loucura passou a ser manual: tira os modificadores das cópias já nas fichas (uma vez, no Mestre principal). */
async function naurenMigrarLoucuraManual() {
  if (game.users.activeGM !== game.user || game.settings.get("nauren", "migracaoLoucuraManualV1")) return;
  const atores = [...game.actors];
  for (const cena of game.scenes) for (const t of cena.tokens) if (!t.actorLink && t.actor) atores.push(t.actor);
  let n = 0;
  for (const a of atores) {
    const loucuras = a.items.filter(i => i.type === "condicao" && i.name === "Loucura" && (i.system.modificadores ?? []).length);
    if (!loucuras.length) continue;
    await a.updateEmbeddedDocuments("Item", loucuras.map(i => ({ _id: i.id, "system.modificadores": [] }))).catch(err => console.warn("Nauren RPG | Loucura manual", a.name, err));
    n += loucuras.length;
  }
  await game.settings.set("nauren", "migracaoLoucuraManualV1", true);
  if (n) console.log(`Nauren RPG | Loucura agora é manual: ${n} cópia(s) nas fichas sem os −1.`);
}
// 0.94.22: roda na lista de migrações, depois dos compêndios (ver "naurenPassosDeMigracao").

/** Canalizar o Espírito: a Energia passa a escalar com o NÍVEL (cópias antigas dependiam do rank, que às vezes não subia). */
async function naurenMigrarCanalizarPorNivel() {
  if (game.users.activeGM !== game.user || game.settings.get("nauren", "migracaoCanalizarNivelV1")) return;
  const FORM = "-(1+min(1,max(0,@nivel-3))+min(1,max(0,@nivel-8))+min(1,max(0,@nivel-15))+@atacouNesteTurno)";
  const atores = [...game.actors];
  for (const cena of game.scenes) for (const t of cena.tokens) if (!t.actorLink && t.actor) atores.push(t.actor);
  let n = 0;
  for (const a of atores) {
    const itens = a.items.filter(i => i.type === "habilidade" && i.name === "Canalizar o Espírito");
    for (const it of itens) {
      const acoes = foundry.utils.deepClone(it.system.acoes ?? []);
      let mudou = false;
      for (const ac of acoes) for (const g of (ac.gastosRecurso ?? [])) {
        if (g.recurso === "recursoCustom:energia" && g.quantidade !== FORM) { g.quantidade = FORM; g.quantidadePorRank = []; mudou = true; }
      }
      if (mudou) { await it.update({ "system.acoes": acoes }).catch(err => console.warn("Nauren RPG | Canalizar por nível", a.name, err)); n++; }
    }
  }
  await game.settings.set("nauren", "migracaoCanalizarNivelV1", true);
  if (n) console.log(`Nauren RPG | Canalizar o Espírito agora escala com o nível: ${n} cópia(s) atualizada(s).`);
}
// 0.94.22: roda na lista de migrações, depois dos compêndios (ver "naurenPassosDeMigracao").

/** Duas armas: o 1º Ataque Básico pago no turno fica guardado aqui (por personagem), para o 2º sair sem custo. */
const naurenDuasArmasPendente = new Map();
/** Extra de Estamina das Condições (Amedrontado/Pânico/Pavor): vale o maior estágio. { extra, nomes } */
function naurenExtraEstaminaCondicoes(actor) {
  const cond = (actor?.items ?? []).filter(i => i.type === "condicao" && i.system.ativo !== false && !naurenEhCondicaoModelo(i) && (i.system.custoEstaminaExtraAcoes || 0) > 0);
  const extra = cond.reduce((t, i) => Math.max(t, i.system.custoEstaminaExtraAcoes || 0), 0);
  return { extra, nomes: cond.filter(i => (i.system.custoEstaminaExtraAcoes || 0) === extra).map(i => i.name) };
}
/** Este Ataque Básico seria o 2º com duas armas (sem custo)? Só prevê, não muda nada. */
function naurenPreverDuasArmasGratis(actor, item, acao) {
  const combate = game.combat?.started ? game.combat : null;
  if (!combate || item?.type !== "arma" || !acao?.ehAtaque || /pesad/i.test(String(acao.nome ?? ""))) return null;
  if (!["Leve", "Média"].includes(item.system.categoria)) return null;
  if (actor.items.filter(i => i.type === "arma" && i.system.equipado && ["Leve", "Média"].includes(i.system.categoria)).length < 2) return null;
  const ant = naurenDuasArmasPendente.get(actor.uuid);
  return (ant && ant.turno === `${combate.id}:${combate.round}:${combate.turn}` && ant.armaId !== item.id) ? ant.armaNome : null;
}

/**
 * Quem conta como "do grupo" de um personagem (para bênçãos como o Druidismo): só quem tem token
 * na MESMA cena e do mesmo lado. Não usa o ator Grupo (as mesas mudam de grupo) e fichas paradas
 * só na aba Atores nunca contam (servidor com muitas fichas).
 */
function naurenAliadosDoGrupo(actor) {
  const aliados = new Set();
  if (!actor) return aliados;
  for (const cena of game.scenes) {
    const meus = cena.tokens.filter(t => t.actor && (t.actor === actor || (t.actorLink && t.actorId === actor.id)));
    if (!meus.length) continue;
    const lado = meus[0].disposition;
    for (const t of cena.tokens) if (t.actor && t.disposition === lado) aliados.add(t.actor);
  }
  return aliados;
}


